    (NVS, "    return b.pages_formatees > 0 ? Contenu::SansDonnee : Contenu::Vide;", "    return Contenu::Vide;", T_SEC, "page_formatee_sans_entree_est_sans_donnee",
     "une partition formatée mais sans donnée est prise pour vierge"),
